package com.catalogix.audit.config; import com.catalogix.audit.service.AuditService; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.stereotype.Component; import org.springframework.amqp.core.Message; import tools.jackson.databind.json.JsonMapper; import java.util.Map; @Component public class EventListener{final AuditService svc;final JsonMapper mapper=new JsonMapper();public EventListener(AuditService s){svc=s;}@RabbitListener(queues="audit.all-events")public void on(Message message){try{String key=message.getMessageProperties().getReceivedRoutingKey();Map<?,?> payload=mapper.readValue(message.getBody(),Map.class);svc.record(key,payload);}catch(Exception ignored){}}}
